import subprocess
import time
import json
import platform

LOGFILE_PATH = "logfile.log"


def _get_windows_cpu_usage():
    try:
        output = subprocess.check_output(
            ["wmic", "cpu", "get", "loadpercentage", "/value"],
            text=True,
            stderr=subprocess.DEVNULL,
        )
    except Exception:
        return 0.0

    values = []
    for line in output.splitlines():
        line = line.strip()
        if line.lower().startswith("loadpercentage="):
            try:
                values.append(float(line.split("=", 1)[1].strip()))
            except ValueError:
                continue

    return sum(values) / len(values) if values else 0.0


def _get_unix_cpu_usage():
    try:
        output = subprocess.check_output(
            ["top", "-bn1"],
            text=True,
            stderr=subprocess.DEVNULL,
        )
    except Exception:
        try:
            output = subprocess.check_output(
                ["sh", "-c", "ps -A -o %cpu= | awk '{sum+=$1} END {print sum}'"],
                text=True,
                stderr=subprocess.DEVNULL,
            )
            return float(output.strip() or 0.0)
        except Exception:
            return 0.0

    for line in output.splitlines():
        stripped = line.strip()
        if "Cpu(s)" in stripped or "CPU:" in stripped or stripped.startswith("%Cpu"):
            cleaned = (
                stripped.replace("%Cpu(s):", "")
                .replace("Cpu(s):", "")
                .replace("%Cpu:", "")
                .strip()
            )
            parts = [part.strip() for part in cleaned.split(",")]

            idle_value = None
            total_non_idle = 0.0
            found_metric = False

            for part in parts:
                tokens = part.split()
                if len(tokens) < 2:
                    continue
                try:
                    value = float(tokens[0])
                except ValueError:
                    continue

                label = tokens[1]
                found_metric = True
                if label == "id":
                    idle_value = value
                else:
                    total_non_idle += value

            if idle_value is not None:
                return max(0.0, min(100.0, 100.0 - idle_value))
            if found_metric:
                return max(0.0, min(100.0, total_non_idle))

    return 0.0


def _get_cpu_usage():
    system_name = platform.system().lower()
    if system_name.startswith("win"):
        return _get_windows_cpu_usage()
    return _get_unix_cpu_usage()


def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("interval and duration must be greater than zero")

    interval = float(interval)
    duration = float(duration)

    records = []
    start = time.monotonic()
    end_time = start + duration
    next_sample_time = start

    while True:
        now = time.monotonic()
        if now < next_sample_time:
            time.sleep(next_sample_time - now)

        records.append(
            {
                "timestamp": time.strftime("%Y-%m-%dT%H:%M:%S", time.localtime()),
                "cpu_usage": _get_cpu_usage(),
            }
        )

        next_sample_time += interval
        if next_sample_time > end_time:
            break

    try:
        with open(LOGFILE_PATH, "w", encoding="utf-8") as log_file:
            json.dump(records, log_file, ensure_ascii=False, indent=2)
    except OSError:
        return None

    return LOGFILE_PATH
